                          </div>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* YouTube Search */}
            {socialPlatform === 'youtube' && (
              <div>
                <div style={{ marginBottom: '32px' }}>
                  <label style={{ 
                    display: 'block',
                    fontSize: '13px',
                    fontWeight: '500',
                    color: '#000000',
                    marginBottom: '12px',
                    textTransform: 'uppercase',
                    letterSpacing: '0.5px'
                  }}>
                    Search YouTube Videos
                  </label>
                  <div style={{ display: 'flex', gap: '12px' }}>
                    <input
                      type="text"
                      value={youtubeSearch}
                      onChange={(e) => setYoutubeSearch(e.target.value)}
                      onKeyPress={(e) => e.key === 'Enter' && searchYouTube()}
                      placeholder="Search for videos, channels, or topics..."
                      style={{
                        flex: 1,
                        padding: '14px 20px',
                        border: '1px solid #f0f0f0',
                        borderRadius: '10px',
                        fontSize: '14px',
                        outline: 'none',
                        transition: 'all 0.2s'
                      }}
                      onFocus={(e) => e.target.style.borderColor = '#6366f1'}
                      onBlur={(e) => e.target.style.borderColor = '#f0f0f0'}
                    />
                    <button
                      onClick={searchYouTube}
                      disabled={socialLoading}
                      style={{
                        padding: '14px 32px',
                        background: '#6366f1',
                        color: '#ffffff',
                        border: 'none',
                        borderRadius: '10px',
                        fontSize: '14px',
                        fontWeight: '600',
                        cursor: socialLoading ? 'default' : 'pointer',
                        opacity: socialLoading ? 0.6 : 1,
                        transition: 'all 0.2s'
                      }}
                    >
                      {socialLoading ? 'Searching...' : 'Search'}
                    </button>
                  </div>
                </div>

                {/* YouTube Results */}
                {youtubeVideos.length > 0 && (
                  <div>
                    <h3 style={{
                      fontSize: '13px',
                      fontWeight: '500',
                      color: '#000000',
                      marginBottom: '16px',
                      textTransform: 'uppercase',
                      letterSpacing: '0.5px'
                    }}>
                      Search Results ({youtubeVideos.length})
                    </h3>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '20px' }}>
                      {youtubeVideos.map((video, idx) => (
                        <a
                          key={idx}
                          href={`https://www.youtube.com/watch?v=${video.videoId}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          style={{
                            display: 'block',
                            background: '#ffffff',
                            border: '1px solid #f0f0f0',
                            borderRadius: '12px',
                            overflow: 'hidden',
                            textDecoration: 'none',
                            boxShadow: '0 4px 24px rgba(0, 0, 0, 0.04)',
                            transition: 'all 0.2s'
                          }}
                          onMouseOver={(e) => {
                            e.currentTarget.style.boxShadow = '0 8px 32px rgba(0, 0, 0, 0.08)';
                            e.currentTarget.style.transform = 'translateY(-2px)';
                          }}
                          onMouseOut={(e) => {
                            e.currentTarget.style.boxShadow = '0 4px 24px rgba(0, 0, 0, 0.04)';
                            e.currentTarget.style.transform = 'translateY(0)';
                          }}
                        >
                          {video.thumbnail && (
                            <img
                              src={video.thumbnail}
                              alt={video.title}
                              style={{
                                width: '100%',
                                height: '180px',
                                objectFit: 'cover'
                              }}
                            />
                          )}
                          <div style={{ padding: '16px' }}>
                            <h4 style={{
                              margin: '0 0 8px 0',
                              fontSize: '14px',
                              fontWeight: '600',
                              color: '#000000',
                              lineHeight: '1.4',
                              display: '-webkit-box',
                              WebkitLineClamp: 2,
                              WebkitBoxOrient: 'vertical',
                              overflow: 'hidden'
                            }}>
                              {video.title}
                            </h4>
                            <div style={{
                              fontSize: '12px',
                              color: '#666666',
                              marginBottom: '8px'
                            }}>
                              {video.channelTitle}
                            </div>
                            <div style={{
                              fontSize: '11px',
                              color: '#999999'
                            }}>
                              {video.publishedAt && new Date(video.publishedAt).toLocaleDateString()}
                            </div>
                          </div>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* TikTok Placeholder */}
            {socialPlatform === 'tiktok' && (
              <div style={{
                padding: '60px 20px',
                textAlign: 'center',
                color: '#999999',
                border: '1px solid #f0f0f0',
                borderRadius: '12px',
                background: '#fafafa'
              }}>
                TikTok integration: View profile info and scheduled posts
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

