import React, { useEffect, useState, useCallback } from 'react';

/**
 * SlidePresenter - Fullscreen presentation mode
 * 
 * Features:
 * - Always-visible exit button (ESC is captured by widget framework)
 * - Keyboard navigation (arrows, space, numbers)
 * - Click to advance
 * - 16:9 aspect ratio maintained
 */
export default function SlidePresenter({
  slides,
  initialSlideIndex,
  onClose
}) {
  const [currentIndex, setCurrentIndex] = useState(initialSlideIndex || 0);
  const [showControls, setShowControls] = useState(true);
  const [mouseTimer, setMouseTimer] = useState(null);

  const currentSlide = slides[currentIndex];
  const totalSlides = slides.length;

  const goToSlide = useCallback((direction) => {
    if (direction === 'next' && currentIndex < totalSlides - 1) {
      setCurrentIndex(prev => prev + 1);
    } else if (direction === 'prev' && currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  }, [currentIndex, totalSlides]);

  const jumpToSlide = useCallback((index) => {
    if (index >= 0 && index < totalSlides) {
      setCurrentIndex(index);
    }
  }, [totalSlides]);

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      switch (e.key) {
        case 'ArrowRight':
        case 'ArrowDown':
        case ' ':
          e.preventDefault();
          goToSlide('next');
          break;
        case 'ArrowLeft':
        case 'ArrowUp':
          e.preventDefault();
          goToSlide('prev');
          break;
        case 'Home':
          e.preventDefault();
          jumpToSlide(0);
          break;
        case 'End':
          e.preventDefault();
          jumpToSlide(totalSlides - 1);
          break;
        default:
          if (/^[1-9]$/.test(e.key)) {
            const num = parseInt(e.key, 10);
            if (num <= totalSlides) jumpToSlide(num - 1);
          }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [goToSlide, jumpToSlide, totalSlides]);

  // Auto-hide controls (but exit button stays visible)
  useEffect(() => {
    const handleMouseMove = () => {
      setShowControls(true);
      if (mouseTimer) clearTimeout(mouseTimer);
      const timer = setTimeout(() => setShowControls(false), 3000);
      setMouseTimer(timer);
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      if (mouseTimer) clearTimeout(mouseTimer);
    };
  }, [mouseTimer]);

  const handleClick = (e) => {
    if (e.target.closest('[data-control]')) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    if (x < rect.width / 3) goToSlide('prev');
    else goToSlide('next');
  };

  if (!currentSlide) return null;

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        backgroundColor: '#000',
        zIndex: 99999,
        display: 'flex',
        flexDirection: 'column'
      }}
      onClick={handleClick}
    >
      {/* EXIT BUTTON - Always visible, top-right corner */}
      <button
        data-control
        onClick={(e) => { e.stopPropagation(); onClose(); }}
        style={{
          position: 'absolute',
          top: '16px',
          right: '16px',
          padding: '10px 20px',
          backgroundColor: '#dc2626',
          border: 'none',
          borderRadius: '8px',
          color: 'white',
          fontSize: '14px',
          fontWeight: 600,
          cursor: 'pointer',
          zIndex: 100,
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          boxShadow: '0 2px 10px rgba(0,0,0,0.3)'
        }}
      >
        <span style={{ fontSize: '16px' }}>✕</span>
        Exit Presentation
      </button>

      {/* Slide content - FULLSCREEN, no borders */}
      <div style={{
        flex: 1,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        overflow: 'hidden'
      }}>
        <div style={{
          width: '100vw',
          height: '100vh',
          backgroundColor: '#fff',
          overflow: 'hidden'
        }}>
          <div
            style={{ width: '100%', height: '100%', overflow: 'hidden' }}
            dangerouslySetInnerHTML={{ __html: currentSlide.content || '' }}
          />
        </div>
      </div>

      {/* Bottom controls - auto-hide */}
      <div
        data-control
        style={{
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          padding: '20px 32px',
          background: 'linear-gradient(transparent, rgba(0,0,0,0.9))',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          gap: '24px',
          opacity: showControls ? 1 : 0,
          transition: 'opacity 0.3s',
          pointerEvents: showControls ? 'auto' : 'none'
        }}
      >
        <button
          onClick={(e) => { e.stopPropagation(); goToSlide('prev'); }}
          disabled={currentIndex === 0}
          style={{
            padding: '10px 20px',
            backgroundColor: 'rgba(255,255,255,0.15)',
            border: 'none',
            borderRadius: '6px',
            color: currentIndex === 0 ? '#555' : '#fff',
            fontSize: '14px',
            cursor: currentIndex === 0 ? 'not-allowed' : 'pointer'
          }}
        >
          ← Previous
        </button>

        {/* Slide indicators */}
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          {slides.map((_, i) => (
            <button
              key={i}
              onClick={(e) => { e.stopPropagation(); jumpToSlide(i); }}
              style={{
                width: i === currentIndex ? '28px' : '10px',
                height: '10px',
                borderRadius: '5px',
                border: 'none',
                backgroundColor: i === currentIndex ? '#fff' : 'rgba(255,255,255,0.3)',
                cursor: 'pointer',
                transition: 'all 0.2s'
              }}
            />
          ))}
        </div>

        <button
          onClick={(e) => { e.stopPropagation(); goToSlide('next'); }}
          disabled={currentIndex === totalSlides - 1}
          style={{
            padding: '10px 20px',
            backgroundColor: 'rgba(255,255,255,0.15)',
            border: 'none',
            borderRadius: '6px',
            color: currentIndex === totalSlides - 1 ? '#555' : '#fff',
            fontSize: '14px',
            cursor: currentIndex === totalSlides - 1 ? 'not-allowed' : 'pointer'
          }}
        >
          Next →
        </button>

        <div style={{ color: '#888', fontSize: '14px', marginLeft: '16px' }}>
          {currentIndex + 1} / {totalSlides}
        </div>
      </div>

      {/* Navigation hint - top left */}
      <div
        data-control
        style={{
          position: 'absolute',
          top: '16px',
          left: '16px',
          padding: '10px 14px',
          backgroundColor: 'rgba(0,0,0,0.7)',
          borderRadius: '6px',
          opacity: showControls ? 1 : 0,
          transition: 'opacity 0.3s'
        }}
      >
        <div style={{ color: '#888', fontSize: '11px' }}>Navigate</div>
        <div style={{ color: '#ccc', fontSize: '12px' }}>← → arrows • Space • Click</div>
      </div>
    </div>
  );
}

sources.components/SlideThumbnails.jsx:
import React, { useState } from 'react';

/**
 * SlideThumbnails - Sidebar with slide thumbnails
 * 
 * Features:
 * - Drag and drop reordering
 * - Context menu for duplicate/delete
 * - Visual preview of each slide
 */
export default function SlideThumbnails({
  slides,
  currentSlideIndex,
  onSelectSlide,
  onDeleteSlide,
  onDuplicateSlide,
  onReorderSlides,
  onAddSlide
}) {
  const [draggedIndex, setDraggedIndex] = useState(null);
  const [dragOverIndex, setDragOverIndex] = useState(null);
  const [contextMenu, setContextMenu] = useState(null);

  const handleDragStart = (e, index) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e, index) => {
    e.preventDefault();
    if (draggedIndex !== null && draggedIndex !== index) {
      setDragOverIndex(index);
    }
  };

  const handleDrop = (e, toIndex) => {
    e.preventDefault();
    if (draggedIndex !== null && draggedIndex !== toIndex) {
      onReorderSlides(draggedIndex, toIndex);
    }
    setDraggedIndex(null);
    setDragOverIndex(null);
  };

  const handleDragEnd = () => {
    setDraggedIndex(null);
    setDragOverIndex(null);
  };

  const handleContextMenu = (e, index) => {
    e.preventDefault();
    setContextMenu({ x: e.clientX, y: e.clientY, index });
  };

  return (
    <div
      style={{
        width: '200px',
        backgroundColor: '#0a0a0a',
        borderRight: '1px solid #262626',
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden'
      }}
      onClick={() => setContextMenu(null)}
    >
      {/* Header */}
      <div style={{
        padding: '12px 14px',
        borderBottom: '1px solid #262626',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center'
      }}>
        <span style={{
          fontSize: '12px',
          fontWeight: 600,
          color: '#737373',
          textTransform: 'uppercase',
          letterSpacing: '0.5px'
        }}>
          Slides
        </span>
        <button
          onClick={onAddSlide}
          style={{
            width: '24px',
            height: '24px',
            borderRadius: '4px',
            border: '1px solid #404040',
            backgroundColor: 'transparent',
            color: '#a3a3a3',
            cursor: 'pointer',
            fontSize: '14px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}
          title="Add slide"
        >
          +
        </button>
      </div>

      {/* Slides list */}
      <div style={{
        flex: 1,
        overflowY: 'auto',
        padding: '10px'
      }}>
        {slides.map((slide, index) => (
          <div
            key={slide.id}
            draggable
            onDragStart={(e) => handleDragStart(e, index)}
            onDragOver={(e) => handleDragOver(e, index)}
            onDragLeave={() => setDragOverIndex(null)}
            onDrop={(e) => handleDrop(e, index)}
            onDragEnd={handleDragEnd}
            onClick={() => onSelectSlide(index)}
            onContextMenu={(e) => handleContextMenu(e, index)}
            style={{
              marginBottom: '8px',
              opacity: draggedIndex === index ? 0.4 : 1,
              transform: dragOverIndex === index ? 'translateY(2px)' : 'none',
              transition: 'all 0.1s'
            }}
          >
            {/* Drop indicator */}
            {dragOverIndex === index && (
              <div style={{
                height: '2px',
                backgroundColor: '#fafafa',
                borderRadius: '1px',
                marginBottom: '4px'
              }} />
            )}

            {/* Thumbnail card */}
            <div style={{
              position: 'relative',
              aspectRatio: '16 / 9',
              backgroundColor: '#171717',
              borderRadius: '6px',
              border: currentSlideIndex === index ? '2px solid #fafafa' : '1px solid #262626',
              overflow: 'hidden',
              cursor: 'pointer'
            }}>
              {/* Slide number */}
              <div style={{
                position: 'absolute',
                top: '4px',
                left: '4px',
                padding: '2px 6px',
                backgroundColor: currentSlideIndex === index ? '#fafafa' : 'rgba(0,0,0,0.7)',
                color: currentSlideIndex === index ? '#0a0a0a' : '#a3a3a3',
                borderRadius: '3px',
                fontSize: '10px',
                fontWeight: 600,
                zIndex: 1
              }}>
                {index + 1}
              </div>

              {/* Mini preview */}
              <div
                style={{
                  transform: 'scale(0.12)',
                  transformOrigin: 'top left',
                  width: '833%',
                  height: '833%',
                  pointerEvents: 'none',
                  backgroundColor: '#fff'
                }}
                dangerouslySetInnerHTML={{ __html: slide.content || '' }}
              />
            </div>
          </div>
        ))}

        {slides.length === 0 && (
          <div style={{
            padding: '32px 16px',
            textAlign: 'center',
            color: '#525252',
            fontSize: '12px'
          }}>
            No slides yet
          </div>
        )}
      </div>

      {/* Context menu */}
      {contextMenu && (
        <>
          <div
            style={{ position: 'fixed', inset: 0, zIndex: 99 }}
            onClick={() => setContextMenu(null)}
          />
          <div style={{
            position: 'fixed',
            top: contextMenu.y,
            left: contextMenu.x,
            backgroundColor: '#171717',
            border: '1px solid #262626',
            borderRadius: '6px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.5)',
            zIndex: 100,
            minWidth: '120px',
            overflow: 'hidden'
          }}>
            <button
              onClick={() => { onDuplicateSlide(contextMenu.index); setContextMenu(null); }}
              style={{
                width: '100%',
                padding: '8px 12px',
                border: 'none',
                backgroundColor: 'transparent',
                color: '#d4d4d4',
                fontSize: '12px',
                textAlign: 'left',
                cursor: 'pointer'
              }}
              onMouseEnter={(e) => e.target.style.backgroundColor = '#262626'}
              onMouseLeave={(e) => e.target.style.backgroundColor = 'transparent'}
            >
              Duplicate
            </button>
            {slides.length > 1 && (
              <button
                onClick={() => { onDeleteSlide(contextMenu.index); setContextMenu(null); }}
                style={{
                  width: '100%',
                  padding: '8px 12px',
                  border: 'none',
                  backgroundColor: 'transparent',
                  color: '#ef4444',
                  fontSize: '12px',
                  textAlign: 'left',
                  cursor: 'pointer'
                }}
                onMouseEnter={(e) => e.target.style.backgroundColor = '#262626'}
                onMouseLeave={(e) => e.target.style.backgroundColor = 'transparent'}
              >
                Delete
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

