            className={`pb-2 font-medium transition-all ${
              activeTab === 'insights' ? 'text-blue-500' : 'text-gray-400'
            }`}
            style={{
              borderBottom: activeTab === 'insights' ? '2px solid #3b82f6' : '2px solid transparent'
